$markets = Import-Csv "$PSScriptRoot/scaninbox-campaigns.csv"
$all = @(); $keywords = @(); $adgroups = @(); $ads = @()
foreach ($line in ($data.Trim() -split "`n")) {
 $v = $line.Trim() -split '\|'; $code=$v[0]; $market=$markets | Where-Object Language -eq $code
 if (!$market) { throw "Missing market: $code" }
 $headlines=@($v[3],$v[1],$v[2],$v[4],$v[5],$v[6],'ScanInbox by inbox.eu','Microsoft 365 SMTP')
 foreach($h in $headlines){if($h.Length -gt 30){throw "Headline too long ($($h.Length)): $h"}}
 foreach($d in @($v[7],$v[8])){if($d.Length -gt 90){throw "Description too long ($($d.Length)): $d"}}
 $groups=@('Printer SMTP','Scan-to-Email Setup','Microsoft 365 Alternative')
 for($i=0;$i -lt 3;$i++){
  $adgroups += [pscustomobject]@{'Row Type'='Ad group';Action='Add';Campaign=$market.Campaign;'Ad group'=$groups[$i];'Ad group status'='Enabled';'Default max. CPC'='0.90'}
  $ad=[ordered]@{'Row Type'='Ad';Action='Add';'Ad status'='Enabled';Campaign=$market.Campaign;'Ad group'=$groups[$i];'Ad type'='Responsive search ad'}
  for($j=0;$j -lt $headlines.Count;$j++){$ad["Headline $($j+1)"]=$headlines[$j]}
  $ad['Headline 1 position']='1';$ad['Description 1']=$v[7];$ad['Description 2']=$v[8];$ad['Final URL']="https://scaninbox.me/$code/"
  $ads += [pscustomobject]$ad
  foreach($term in ($v[9+$i] -split ';')){foreach($match in @('Exact','Phrase')){
   $keywords += [pscustomobject]@{'Row Type'='Keyword';Action='Add';Campaign=$market.Campaign;'Ad group'=$groups[$i];Keyword=$term;'Type'="$match match";'Keyword status'='Enabled';'Default max. CPC'='0.90'}
  }}
 }
}
$adgroups | Export-Csv "$PSScriptRoot/scaninbox-ad-groups.csv" -NoTypeInformation -Encoding utf8
$ads | Export-Csv "$PSScriptRoot/scaninbox-ads.csv" -NoTypeInformation -Encoding utf8
$keywords | Export-Csv "$PSScriptRoot/scaninbox-keywords.csv" -NoTypeInformation -Encoding utf8
Write-Output "Generated $($markets.Count) campaigns, $($adgroups.Count) ad groups, $($ads.Count) ads, $($keywords.Count) keywords."
